const _flow = { sourceVersion: 3, inputs: { rows: { type: "array" } } }

function ConstLoop({ input, config, result }) {
  const doubled = json.array({ itemType: { type: "number" } })
  for (const item of input.rows) {
    const twice = item * 2
    if (twice > 0) {
      const shown = twice
      doubled.push(shown)
    }
  }
  let n = 0
  const steps = json.array({ itemType: { type: "number" } })
  while (n < 3) {
    const next = n + 10
    steps.push(next)
    n++
  }
  return { doubled, steps }
}
